import 'dart:io';

void main() {
  final file = File('frontend/lib/features/dashboard/presentation/dashboard_screen.dart');
  String c = file.readAsStringSync().replaceAll('\r\n', '\n');

  // ── RepaymentCard: update colors and layout ───────────────────────────────
  c = c
    .replaceAll(
      "    final bg     = isBorrow ? Colors.red.shade50   : Colors.green.shade50;\n",
      "    final bg     = isBorrow ? const Color(0xFFFFECEC) : const Color(0xFFECF9EC);\n")
    .replaceAll(
      "    final color  = isBorrow ? Colors.red.shade700 : Colors.green.shade700;\n",
      "    final color  = isBorrow ? Colors.red.shade600 : Colors.green.shade600;\n");

  // ── RepaymentCard: replace bordered card with shadow card ─────────────────
  c = c.replaceAll(
    "    return Container(\n      margin: const EdgeInsets.only(bottom: 10),\n      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),\n      decoration: BoxDecoration(\n        color: bg,\n        borderRadius: BorderRadius.circular(14),\n        border: Border.all(color: color.withValues(alpha: 0.25)),\n      ),\n      child: Row(\n        children: [\n          CircleAvatar(\n            radius: 20,\n            backgroundColor: color.withValues(alpha: 0.15),\n            child: Icon(icon, color: color, size: 18),\n          ),\n          const SizedBox(width: 12),\n          Expanded(\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Text(\n                  label,\n                  style: TextStyle(\n                    fontWeight: FontWeight.bold,\n                    color: color,\n                    fontSize: 13,\n                  ),\n                ),\n                Text(\n                  DateFormat('MMM d, h:mm a').format(repayment.date),\n                  style: TextStyle(\n                      fontSize: 11, color: Colors.grey.shade500),\n                ),\n              ],\n            ),\n          ),\n          Text(\n            '\$prefix\${repayment.amount.toStringAsFixed(0)}',\n            style: TextStyle(\n              fontWeight: FontWeight.bold,\n              fontSize: 15,\n              color: color,\n            ),\n          ),\n        ],\n      ),\n    );",
    "    return Container(\n      margin: const EdgeInsets.only(bottom: 10),\n      decoration: BoxDecoration(\n        color: bg,\n        borderRadius: BorderRadius.circular(16),\n        boxShadow: [\n          BoxShadow(\n            color: Colors.black.withValues(alpha: 0.04),\n            blurRadius: 8,\n            offset: const Offset(0, 3),\n          ),\n        ],\n      ),\n      child: Padding(\n        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),\n        child: Row(\n          children: [\n            CircleAvatar(\n              radius: 22,\n              backgroundColor: color.withValues(alpha: 0.15),\n              child: Icon(icon, color: color, size: 18),\n            ),\n            const SizedBox(width: 14),\n            Expanded(\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Text(\n                    label,\n                    style: const TextStyle(\n                      fontWeight: FontWeight.w700,\n                      color: Colors.black87,\n                      fontSize: 14,\n                    ),\n                  ),\n                  const SizedBox(height: 2),\n                  Text(\n                    DateFormat('MMM d, h:mm a').format(repayment.date),\n                    style: TextStyle(fontSize: 11, color: Colors.grey.shade500),\n                  ),\n                ],\n              ),\n            ),\n            Text(\n              '\$prefix\${repayment.amount.toStringAsFixed(0)}',\n              style: TextStyle(\n                fontWeight: FontWeight.bold,\n                fontSize: 15,\n                color: color,\n              ),\n            ),\n          ],\n        ),\n      ),\n    );");

  // ── TransactionCard: insert compact non-creation-day path ─────────────────
  const oldColorBlock =
    "\n    Color amountColor  = Colors.redAccent;\n    String amountPrefix = '- ';\n    Color containerColor = Colors.white;\n    Color borderColor  = Colors.grey.shade100;\n    Color iconBgColor  = primaryTeal.withValues(alpha: 0.1);\n    Color iconColor    = primaryTeal;\n\n    if (isSpecial) {\n      if (isCleared) {\n        amountColor   = isLoan ? Colors.green : Colors.redAccent;\n        amountPrefix  = isLoan ? '+ ' : '- ';\n      } else {\n        amountPrefix  = '⏳ ';\n        if (isLoan) {\n          amountColor   = Colors.green.shade700;\n          containerColor = Colors.green.shade50;\n          borderColor   = Colors.green.shade200;\n          iconBgColor   = Colors.green.withValues(alpha: 0.2);\n          iconColor     = Colors.green.shade700;\n        } else {\n          amountColor   = Colors.red.shade700;\n          containerColor = Colors.red.shade50;\n          borderColor   = Colors.red.shade200;\n          iconBgColor   = Colors.red.withValues(alpha: 0.2);\n          iconColor     = Colors.red.shade700;\n        }\n      }\n    }\n";

  const newColorBlock =
    "\n    final Color accentColor = isLoan\n        ? Colors.green.shade600\n        : isBorrow\n            ? Colors.red.shade600\n            : primaryTeal;\n    final Color bgColor = isSpecial && !isCleared\n        ? (isLoan ? const Color(0xFFECF9EC) : const Color(0xFFFFECEC))\n        : Colors.white;\n\n    // Non-creation-day: compact tappable tracking card\n    if (isSpecial && !isCreationDay && !isCleared) {\n      return Container(\n        margin: const EdgeInsets.only(bottom: 10),\n        decoration: BoxDecoration(\n          color: bgColor,\n          borderRadius: BorderRadius.circular(16),\n          boxShadow: [\n            BoxShadow(\n              color: Colors.black.withValues(alpha: 0.04),\n              blurRadius: 8,\n              offset: const Offset(0, 3),\n            ),\n          ],\n        ),\n        child: InkWell(\n          borderRadius: BorderRadius.circular(16),\n          onTap: onRecordPayment,\n          child: Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),\n            child: Row(\n              children: [\n                CircleAvatar(\n                  radius: 22,\n                  backgroundColor: accentColor.withValues(alpha: 0.15),\n                  child: Icon(getCategoryIcon(tx.category),\n                      color: accentColor, size: 20),\n                ),\n                const SizedBox(width: 14),\n                Expanded(\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(tx.label,\n                          style: const TextStyle(\n                              fontWeight: FontWeight.w700,\n                              color: Colors.black87,\n                              fontSize: 14)),\n                      const SizedBox(height: 2),\n                      Text(\n                        tx.isPartiallyPaid\n                            ? '\${tx.category} \\u2022 Rs \${tx.amountPaid.toStringAsFixed(0)} paid'\n                            : '\${tx.category} \\u2022 Tap to pay',\n                        style: TextStyle(\n                            fontSize: 12,\n                            color: accentColor,\n                            fontWeight: FontWeight.w600),\n                      ),\n                    ],\n                  ),\n                ),\n                Column(\n                  crossAxisAlignment: CrossAxisAlignment.end,\n                  mainAxisAlignment: MainAxisAlignment.center,\n                  children: [\n                    Text(\n                      '\\u23f3 Rs \${tx.remainingAmount.toStringAsFixed(0)}',\n                      style: TextStyle(\n                          fontWeight: FontWeight.bold,\n                          color: accentColor,\n                          fontSize: 15),\n                    ),\n                    if (tx.isPartiallyPaid)\n                      Text(\n                        'Paid: \${tx.amountPaid.toStringAsFixed(0)} / \${tx.amount.toStringAsFixed(0)}',\n                        style: TextStyle(\n                            fontSize: 10,\n                            color: accentColor.withValues(alpha: 0.75)),\n                      ),\n                  ],\n                ),\n              ],\n            ),\n          ),\n        ),\n      );\n    }\n\n    Color amountColor   = Colors.redAccent;\n    String amountPrefix = '- ';\n    final Color containerColor = bgColor;\n    final Color borderColor    = isSpecial && !isCleared\n        ? accentColor.withValues(alpha: 0.2) : Colors.grey.shade100;\n    final Color iconBgColor    = isCleared\n        ? primaryTeal.withValues(alpha: 0.1) : accentColor.withValues(alpha: 0.15);\n    final Color iconColor      = isCleared ? primaryTeal : accentColor;\n\n    if (isSpecial) {\n      if (isCleared) {\n        amountColor  = isLoan ? Colors.green : Colors.redAccent;\n        amountPrefix = isLoan ? '+ ' : '- ';\n      } else {\n        amountPrefix = '\\u23f3 ';\n        amountColor  = accentColor;\n      }\n    }\n";

  c = c.replaceAll(oldColorBlock, newColorBlock);

  // Fix subtitle iconColor ref to accentColor
  c = c.replaceAll(
    "                color: isSpecial && !isCleared\n                    ? iconColor\n                    : Colors.grey.shade600,",
    "                color: isSpecial && !isCleared\n                    ? accentColor\n                    : Colors.grey.shade600,");

  print('RepaymentCard updated: ${c.contains("0xFFFFECEC")}');
  print('Compact card inserted: ${c.contains("Non-creation-day")}');

  file.writeAsStringSync(c);
  print('Done!');
}
